class Solution {
public:
    int minimumOperations(vector<int>& nums, int start, int goal) 
    {
        queue<int> que;
        que.push(start); 
        vector<int> visit(1001, 0); 
        int level = 0;

        while(!que.empty()) {
            int size = que.size(); 
            for(int i=0; i<size; i++) {
                int curr = que.front(); 
                que.pop();
                if(curr == goal)
                    return level; 
                if(curr<0 || curr>1000 || visit[curr] == 1)
                    continue; 
                visit[curr] = 1; 
                for(int i=0; i< nums.size(); i++) {
                    que.push(curr + nums[i]);
                    que.push(curr - nums[i]); 
                    que.push(curr ^ nums[i]);                    
                }
            }
            level++; 
        }
        return -1; 
    }
};
